window.RP_SESSION={"id":"S-1b3f9e7b9df7","messages":[{"id":"RP-III-0161124","time":"2026-08-28T20:46:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"단델리온은 장작 하나를 집어 모닥불에 넣습니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161125","time":"2026-08-28T20:46:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-df0906c0708a"]},{"id":"RP-III-0161126","time":"2026-08-28T20:58:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"단델리온은 조용히 숫돌을 꺼냅니다. 손바닥만 한 숫돌입니다. 오래 사용한 탓인지 모서리는 둥글게 닳아 있고, 표면에는 미세한 홈이 곳곳에 패여 있습니다.\n그는 칼집에서 검을 천천히 뽑아낸 뒤, 검날을 눈높이까지 들어 올립니다.\n달빛을 받아 은빛으로 빛나는 검날, 단델리온은 검을 좌우로 조금씩 기울여가며 날을 확인합니다.\n\n“…….”\n\n흠집이 있네요.\n날의 일부가 아주 조금 무뎌져 있습니다.\n그는 검날을 손가락으로 직접 쓸어내리지 않고, 손톱을 날과 평행하게 살짝 대어 상태를 확인합니다.\n그리고 숫돌을 무릎 위에 안정적으로 올려놓은 후, 숫돌에 물을 조금 떨어뜨립니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161127","time":"2026-08-28T21:02:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"검날을 숫돌 위에 비스듬히 눕힙니다.\n\n사각...\n 사각...","characters":["P-df0906c0708a"]},{"id":"RP-III-0161128","time":"2026-08-28T21:05:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"숫돌 위로 미세한 쇳가루와 물이 섞여 흐릅니다.\n\n\"...\"\n\n이번에는 날을 반대쪽으로 뒤집은 뒤, 다시 조심스럽게 검날을 갈아냅니다.\n\n사각...\n 사갓...","characters":["P-df0906c0708a"]},{"id":"RP-III-0161129","time":"2026-08-28T21:16:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"\"좋아, 이 정도면 괜찮은 것 같군.\"","characters":["P-df0906c0708a"]},{"id":"RP-III-0161130","time":"2026-08-28T21:17:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"단델리온은 마음에 드는지 대검을 들고 이리저리 휘둘러봅니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161131","time":"2026-08-28T21:18:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-df0906c0708a"]},{"id":"RP-III-0161132","time":"2026-08-28T21:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'단델리온'의 힘 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0161133","time":"2026-08-28T21:18:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-df0906c0708a"]},{"id":"RP-III-0161134","time":"2026-08-28T21:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 8 = 8\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0161135","time":"2026-08-28T21:20:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"단델리온은 대검을 옆으로 크게 휘둘러봅니다.\n검끝이 지나간 자리의 공기가 갈라지듯 서늘한 소리가 울립니다.\n\n검끝이 아슬아슬하게 옆의 나무를 스칩니다.\n콰직!\n나무껍질이 조금 떨어져 나갑니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161136","time":"2026-08-28T21:25:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n단델리온은 하늘을 바라봅니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161137","time":"2026-08-28T21:28:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"기분 좋은 밤공기가 살랑이고, 어디선가 싱그러운 풀내음이 은은하게 피어오릅니다.\n\n낮의 햇살을 머금었던 풀잎들이 밤이슬에 젖어\n한층 짙어진 향을 내뿜고 있습니다.\n발밑의 풀잎이 바람에 살짝 흔들리고, 차가운 밤공기 사이로 흙과 풀의 향이 스며듭니다.\n\n고요하고 평온한 밤이였습니다.","characters":["P-df0906c0708a"]},{"id":"RP-III-0161138","time":"2026-08-28T21:28:00+09:00","room":"RP III","name":"단델리온","profile":"식물학자 이파리","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-df0906c0708a"]},{"id":"RP-III-0161139","time":"2026-08-28T21:29:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
